<?php
require __DIR__.'/../app/bootstrap.php';security_headers();require_admin();$db=database();$activity=(int)($_GET['activity']??0);$activities=$db->query('SELECT id,admin_name,slug FROM activities ORDER BY admin_name')->fetchAll();$where=$activity?' WHERE i.activity_id=?':'';$q=$db->prepare('SELECT i.*,a.admin_name,a.slug FROM interest_submissions i LEFT JOIN activities a ON a.id=i.activity_id'.$where.' ORDER BY i.id DESC');$q->execute($activity?[$activity]:[]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/template/page.css"><title>Interest submissions</title></head><body><main class="section"><p><a href="/admin/activities.php">Activities</a> · <a href="/admin/export.php<?= $activity?'?activity='.$activity:''?>">Export CSV</a></p><h1>Interest submissions</h1><form method="get"><label>Activity <select name="activity"><option value="">All activities</option><?php foreach($activities as $a):?><option value="<?=$a['id']?>" <?=$activity===(int)$a['id']?'selected':''?>><?=h($a['admin_name'])?> (<?=h($a['slug'])?>)</option><?php endforeach;?></select></label><button>Filter</button></form><p><?=count($rows)?> records</p><?php foreach($rows as $r):$p=json_decode($r['payload_json'],true)?:[];?><details><summary><?=h($r['admin_name']??'Original activity')?> · /<?=h($r['slug']??'')?> · <?=h($r['created_at'])?> — <?=h($r['name'])?> — <?=h($r['email'])?></summary><dl><dt>Activity</dt><dd><?=h($r['admin_name']??'Original activity')?> · /<?=h($r['slug']??'')?></dd><?php foreach($p as $k=>$v):?><dt><?=h($k)?></dt><dd><?=nl2br(h((string)$v))?></dd><?php endforeach;?></dl></details><?php endforeach;?></main></body></html>
